 const C=window.AtlasDaily,L=window.AtlasDailyLibrary,STORE='inner-atlas-daily-v1',$=id=>document.getElementById(id),el=(t,c,txt)=>{const n=document.createElement(t);if(c)n.className=c;if(txt!==undefined)n.textContent=txt;return n;};
 let guest=C.clean(),active=false,day=C.dateKey(),scope='',draftKey='',selectedDay=day,weekOffset=0,readingId='',drafts=new Map(),draftLessons=new Map(),reviewDrafts=new Map(),reviewKey='',dirtyDrafts=new Set(),importCandidate=null;
 try{const raw=localStorage.getItem(STORE);if(raw){const v=JSON.parse(raw);if(v.version!==1)throw Error();guest=C.clean(v);}}catch{toast('修习记录未能读取，请使用之前的修习备份恢复。');}
