 function status(message){$('dailyStatus').textContent=message;}
 function save(next,event){next=C.clean(next);let ok=false;if(getRecord()){ok=saveProfile(next,event);}else{try{localStorage.setItem(STORE,JSON.stringify(next));guest=next;ok=true;}catch{status('浏览器未能保存，内容仍在输入框中。请重试或复制文字留存。');}}if(ok){try{localStorage.setItem('inner-atlas-daily-return',JSON.stringify(getRecord()?{birthday:getRecord().birthday,name:getRecord().name}:{guest:true}));}catch{}}else status('未能保存，本次操作尚未记入足迹。请重试或备份现有记录。');return ok;}
 function ensureEntry(s){if(!s.entries[day])s.entries[day]=C.emptyEntry(C.choose(s,day).id);return s.entries[day];}
 function log(s,date){const e=s.entries[date],l=C.lesson(e.lessonId);return {date,title:'每日修习 · '+date,text:l.title+'\n'+l.quote+'\n出处：'+l.source+(l.url?'\n'+l.url:'')+'\n阅读：'+(e.read?'已读':'未标记')+'\n行动：'+({planned:'待尝试',done:'已尝试',skip:'暂不尝试'}[e.actionState])+'\n我的发现：'+(e.reflection||'未记录')+(e.reviewState?'\n回看：'+({done:'已尝试',partial:'试了一部分',skip:'暂时没有'}[e.reviewState])+' '+e.review:'')};}
 function remember(){if(reviewKey)reviewDrafts.set(reviewKey,{text:$('dailyReviewNote').value,choice:page.querySelector('[name=dailyReviewState]:checked')?.value||''});if(draftKey){draftLessons.set(draftKey,readingId);const value=$('dailyNote').value;drafts.set(draftKey,value);if(value!==($('dailyNote').dataset.saved||''))dirtyDrafts.add(draftKey);else dirtyDrafts.delete(draftKey);}}
