 $('dailyImport').onchange=async()=>{const file=$('dailyImport').files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('文件超过 8 MB');const doc=JSON.parse(await file.text());if(doc.format!=='inner-atlas-daily'||doc.version!==1||!doc.data||doc.data.version!==1||!doc.data.entries||typeof doc.data.entries!=='object'||Array.isArray(doc.data.entries))throw Error('不是支持的修习备份');const candidate=C.clean(doc.data),rawKeys=Object.keys(doc.data.entries);if(rawKeys.some(k=>!C.validDate(k)||!C.lesson(doc.data.entries[k]?.lessonId)))throw Error('包含无效日期或未知课程');if(rawKeys.length>730)throw Error('记录超过 730 天');importCandidate=candidate;const local=state(),added=Object.keys(candidate.entries).filter(k=>!local.entries[k]).length;$('dailyImportMessage').textContent='将补入 '+added+' 天记录；同日期保留本机记录。已有兴趣偏好保持不变。';$('dailyImportDialog').showModal();}catch(error){status('导入未执行：'+error.message);}finally{$('dailyImport').value='';}};
