 $('dailyTime').onchange=()=>{const s=state();s.time=$('dailyTime').value;if(save(s))status('学习时刻已保存；可以下载日历提醒。');};$('dailyCalendar').onclick=()=>{const s=state(),now=new Date(),start=new Date(day+'T'+s.time+':00');if(start<now)start.setDate(start.getDate()+1);const stamp=date=>C.dateKey(date).replaceAll('-','')+'T'+String(date.getHours()).padStart(2,'0')+String(date.getMinutes()).padStart(2,'0')+'00';const end=new Date(start.getTime()+5*60000);download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Inner Atlas//Daily Practice//ZH','BEGIN:VEVENT','UID:inner-atlas-daily-local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'RRULE:FREQ=DAILY','SUMMARY:给自己五分钟 · 今日修习','DESCRIPTION:读一句话，尝试一件小事。请打开本命天赋。','BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:今日修习','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar;charset=utf-8','今日修习提醒.ics');status('日历文件已下载。导入日历后由日历提醒，可在日历中修改或删除。');};
 function stopVoice(){window.speechSynthesis?.cancel();$('dailyStopVoice').hidden=true;$('dailyListen').textContent='朗读本篇';}const canSpeak='speechSynthesis' in window&&'SpeechSynthesisUtterance' in window;$('dailyListen').hidden=!canSpeak;$('dailyListen').onclick=()=>{stopVoice();const l=C.lesson(readingId),utterance=new SpeechSynthesisUtterance(l.title+'。'+l.quote+'。'+l.body+'。'+l.question+'。'+l.action);const local=speechSynthesis.getVoices().find(v=>v.localService&&/^zh/i.test(v.lang));if(!local){status('当前设备没有可用的本地中文语音，可以继续文字阅读。');return;}utterance.voice=local;utterance.lang=local.lang;utterance.rate=.88;utterance.onend=stopVoice;utterance.onerror=()=>{stopVoice();status('当前设备未能朗读，可以继续文字阅读。');};speechSynthesis.speak(utterance);$('dailyStopVoice').hidden=false;$('dailyListen').textContent='正在朗读';};$('dailyStopVoice').onclick=stopVoice;
