  const filamentMaterial=new T.ShaderMaterial({uniforms,transparent:true,depthWrite:false,blending:T.AdditiveBlending,vertexShader:`attribute vec3 target;uniform float uMorph;uniform float uTime;varying float glow;void main(){vec3 p=mix(position,target,smoothstep(0.,1.,uMorph));glow=.2+.8*pow(.5+.5*sin(p.y*5.+p.x*3.-uTime*.7),5.);gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);}`,fragmentShader:`uniform vec3 uColor;varying float glow;void main(){gl_FragColor=vec4(uColor,.09+glow*.25);}`});
