  const starPos=new Float32Array(600*3);for(let i=0;i<600;i++){starPos[i*3]=(rand()-.5)*16;starPos[i*3+1]=(rand()-.5)*10;starPos[i*3+2]=(rand()-.5)*14-3;}const starGeo=new T.BufferGeometry();starGeo.setAttribute('position',new T.BufferAttribute(starPos,3));scene.add(new T.Points(starGeo,new T.PointsMaterial({color:'#aececb',size:.018,transparent:true,opacity:.5,sizeAttenuation:true})));
  function resize(){const box=canvas.parentElement.getBoundingClientRect();if(box.width<2||box.height<2)return;renderer.setSize(box.width,box.height,false);camera.aspect=box.width/box.height;camera.updateProjectionMatrix();world.position.x=box.width>760?1.3:0;camera.position.z=box.width>760?7.6:8.3;dirty=true;}
