  function render(now){requestAnimationFrame(render);const dt=Math.min((now-prev)/1000,.04);prev=now;if(!active||document.hidden)return;if(!paused()){time+=dt*(quiet?.22:1);morph=Math.min(1,morph+dt*.65);dirty=true;}else if(morph<1){morph=1;dirty=true;}if(!dirty)return;dirty=false;uniforms.uTime.value=time;uniforms.uMorph.value=morph;uniforms.uMotion.value=paused()?0:1;world.rotation.set(pitch+(school===2?.45:0),angle+Math.sin(time*.13)*.08,school===1?time*.065:0);frame.rotation.z=-time*.022;points.rotation.y=school===2?time*.09:0;filaments.rotation.y=points.rotation.y;renderer.render(scene,camera);frameCount++;}
  resize();requestAnimationFrame(render);
