function syncVideo(){const go=active&&visible&&!document.hidden&&motion()&&!videoFailed;media.classList.toggle('is-still',!go);if(go){if(video.getAttribute('src')!==tracks[school].video){video.src=tracks[school].video;video.classList.remove('is-ready');}if(video.paused&&!videoPending){videoPending=true;video.play().then(()=>{if(active&&!videoFailed)video.classList.add('is-ready');}).catch(()=>{}).finally(()=>videoPending=false);}}else video.pause();}
