document.addEventListener('keydown',e=>{if(e.key==='Escape'&&soundHelp.open){e.preventDefault();closeSoundHelp(true);return;}if(!stage.classList.contains('dao-immersive'))return;if(e.key==='Escape'){immerse(false);$('daoImmerse').focus();}if(e.key==='Tab'){const nodes=[...controls.querySelectorAll('button,input,select,summary')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(!controls.contains(document.activeElement)||(!e.shiftKey&&document.activeElement===last)){e.preventDefault();first.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}}});
