  const spaces={dao:['山水之间，\n把心放慢。','最近哪件事，你越用力越累？','道 · 云山观势','云山与箫声'],ru:['一卷书里，\n安顿此身。','今天，哪一个小行动能让你更坦然？','儒 · 琴书修身','书院与古琴'],fo:['莲影之间，\n照见此心。','先看见心里的念头，不必急着跟随它。','佛 · 莲池观心','莲池与钟磬']};const space=spaces[school];$('easternHeading').textContent=space[0];$('easternSubtitle').textContent=space[1];$('easternIdentity').textContent=space[2];$('easternForm').textContent=space[3]+' · 原创动态影像';
