 const purpose=make('div','assessment-purpose panel');purpose.innerHTML='<h2>这一步能帮你什么？</h2><p>生日先给出几个探索方向。你补充的经历和自评，用来调整这些方向的先后顺序。比如，表达与创造更熟练时，内容、设计类方向可能排到前面。</p><p>只填有把握的项目；也可以跳过，直接看天赋和发展建议。</p>';purpose.append(button('先看我的天赋与发展方向 ↗',()=>{route('explore');document.querySelector('[data-section="careerSection"]').click();},'primary'));$('assessmentContent').before(purpose);
