 const journalFooter=make('div','journal-footer');journalFooter.innerHTML='<small id="journalCount">0 / 2000</small>';journalFooter.append(button('保存这次发现 ↗',journal,'primary'));$('growthNotes').after(journalFooter);
 const timelineTools=make('div','timeline-tools');[['all','全部记录'],['note','复盘'],['action','行动']].forEach(([key,label])=>{const b=button(label,()=>{timelineFilter=key;filterTimeline();},'filter-chip');b.dataset.filter=key;timelineTools.append(b);});$('timeline').before(timelineTools);
