 function startJournal(q){const field=$('growthNotes'),r=getRecord();if(!r)return;const text=(field.value.trim()?field.value.trim()+'\n\n':'')+q+'\n';if(text.length>2000){toast('笔记已接近字数上限，请先整理内容。');return;}route('growth');field.value=text;field.dispatchEvent(new Event('input',{bubbles:true}));field.focus();field.setSelectionRange(text.length,text.length);field.scrollIntoView({block:'center',behavior:'smooth'});}
