 function decorateRatings(){document.querySelectorAll('.rating-row').forEach((row,i)=>{if(row.querySelector('.rating-choices'))return;row.querySelector('label').after(make('p','rating-description',descriptions[i]));const choices=make('div','rating-choices');choices.setAttribute('role','group');choices.setAttribute('aria-label',order[i]+'评分');for(let value=1;value<=5;value++){const b=button(['很少做到','偶尔做到','通常做到','比较熟练','稳定做到'][value-1],()=>{const input=$('rating-'+i);input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}));},'rating-choice');b.dataset.score=value;b.setAttribute('aria-label',order[i]+' '+value+'分');choices.append(b);}const range=row.querySelector('input[type=range]');range.classList.add('rating-control-internal');range.tabIndex=-1;range.before(choices);});}
 function filterTimeline(){document.querySelectorAll('.timeline-tools button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===timelineFilter)));document.querySelectorAll('.timeline-entry').forEach(n=>n.hidden=timelineFilter!=='all'&&(timelineFilter==='note'?n.dataset.kind!=='note':n.dataset.kind==='note'));let empty=$('timelineFilterEmpty');if(!empty){empty=make('p','timeline-empty','这个分类还没有记录。');empty.id='timelineFilterEmpty';$('timeline').append(empty);}empty.hidden=!getRecord()?.timeline.length||Array.from(document.querySelectorAll('.timeline-entry')).some(n=>!n.hidden);}
