 function refresh(){const r=getRecord();journey.hidden=!r||activePage==='explore';document.body.classList.toggle('interior-page',activePage!=='explore'||!!r&&!document.body.classList.contains('landing'));if(!r){refreshArchives();return;}
  const p=profile(r.birthday),n=Object.keys(r.ratings).length,done=r.completed.filter(Boolean).length;
  $('activeExplorer').textContent=r.name||'探索者';$('activeExplorerMeta').textContent=p.sign.name+' · '+r.birthday;
  const states=['生日画像',n+' / 6 自评',done+' / 4 完成',isDirty()?'有未保存内容':'已保存到本机'];Array.from(steps.children).forEach((b,i)=>{b.querySelector('small').textContent=states[i];b.classList.toggle('active',b.dataset.route===activePage);b.classList.toggle('needs-save',i===3&&isDirty());if(b.dataset.route===activePage)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});
  $('assessmentCount').textContent=n;$('assessmentMeterFill').style.transform='scaleX('+n/6+')';$('evidenceCount').textContent=r.evidence.length+' / 2000';$('journalCount').textContent=r.growthNotes.length+' / 2000';$('growthOrbitCount').textContent=done;growthCompass.style.setProperty('--progress',done*25+'%');
  const next=r.completed.findIndex(v=>!v);$('nextActionTitle').textContent=next<0?'四个行动已完成，回看你的变化。':p.developmentPlan[next].title;$('nextActionDescription').textContent=next<0?'写下一条新发现，让下一次探索有迹可循。':p.developmentPlan[next].detail;
  Array.from(milestones.children).forEach((b,i)=>{b.classList.toggle('done',!!r.completed[i]);b.classList.toggle('current',next===i);b.querySelector('strong').textContent=p.developmentPlan[i].period;b.querySelector('small').textContent=r.completed[i]?'已点亮':next===i?'下一步':'待探索';});
  decorateRatings();document.querySelectorAll('.rating-row').forEach((row,i)=>{row.classList.toggle('rated',!!r.ratings[order[i]]);row.querySelectorAll('.rating-choice').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.score)===r.ratings[order[i]])));});
  document.querySelectorAll('#plan>article').forEach((card,i)=>card.dataset.step=String(i+1).padStart(2,'0'));
  $('connectionMe').textContent=r.name||'你';refreshLens();decorateCards();filterTimeline();refreshArchives();
 }
 function refreshArchives(){const records=getArchive();$('archiveTotal').textContent=records.length;$('archiveActions').textContent=records.reduce((n,r)=>n+r.completed.filter(Boolean).length,0);$('archiveNotes').textContent=records.reduce((n,r)=>n+r.timeline.length,0);}
 function onPage(page){activePage=page;refresh();if(page==='compare'){const select=$('compareArchive');select.replaceChildren(new Option('手动填写另一位探索者',''));getArchive().forEach((r,i)=>{select.append(new Option((r.name||'探索者')+' · '+r.birthday,JSON.stringify([r.birthday,r.name])));});}const section=$(page+'Page');section.classList.remove('page-enter');void section.offsetWidth;section.classList.add('page-enter');}
 function comparisonReady(){waiting.hidden=true;const conversation=make('section','conversation panel');conversation.innerHTML='<div class="section-heading"><div><span class="section-kicker">A CONVERSATION, NOT A VERDICT</span><h2>比结论更有用的，是一次对话。</h2></div><span>记录保存至你的成长时间线</span></div><div class="conversation-tabs" role="group" aria-label="交流主题"></div><p id="conversationPrompt" class="conversation-prompt"></p><label for="conversationNotes">聊完以后，你们发现了什么？</label><textarea id="conversationNotes" maxlength="1980" rows="3" placeholder="记录共同点、不同的做法，或约定的一个小行动。"></textarea><div class="conversation-footer"></div>';
  modes.forEach(([title],i)=>{const b=button(title,()=>{compareMode=i;updatePrompt();},'filter-chip');conversation.querySelector('.conversation-tabs').append(b);});
  const partner=$('compareName').value.trim()||'另一位探索者',partnerDate=$('compareBirthday').value;
  conversation.querySelector('.conversation-footer').append(button('保存交流记录 ↗',()=>{const input=$('conversationNotes'),text=input.value.trim();if(!text){toast('先写下一点交流后的发现。');input.focus();return;}const title='与'+partner+' · '+modes[compareMode][0];const stored='对方生日：'+partnerDate+'\n'+text;const last=getRecord().timeline.at(-1);if(last?.title!==title||last?.text!==stored)appendTimeline('note',title,stored);if(save())toast('交流记录已保存，可以在成长记录中回看。');},'primary'),button('去成长记录查看 →',()=>route('growth'),'text-button'));
  $('comparison').append(conversation);compareMode=0;updatePrompt();
  function updatePrompt(){$('conversationPrompt').textContent=modes[compareMode][1];conversation.querySelectorAll('.conversation-tabs button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===compareMode)));}
 }
 function resetComparison(){waiting.hidden=false;}
 return {refresh,onPage,comparisonReady,resetComparison,filterTimeline};
