$('importFile').onchange=async()=>{
 const file=$('importFile').files[0];if(!file)return;
 try{if(file.size>16777216)throw Error('文件超过 16 MB，请选择本工具导出的 JSON');
 const data=JSON.parse(await file.text());if(data.version!==2||!Array.isArray(data.records)||!data.records.length||data.records.length>20)throw Error('文件格式不支持，请选择本工具导出的版本 2 备份');
 const imported=data.records.map(cleanRecord);let next=archive.slice(),added=0;
 imported.forEach(r=>{if(!next.some(x=>x.birthday===r.birthday&&x.name===r.name)){next.push(r);added++;}});
 if(next.length>20)throw Error('合并后超过 20 份档案，请先整理现有档案');
 if(!added){toast('这些档案已存在，未覆盖现有记录');return;}
 if(confirm('导入 '+added+' 份档案到当前浏览器？同名同生日的现有档案将保留。')&&persist(next)){setPage('archive');toast('已导入 '+added+' 份档案');}
 }catch(e){toast(e instanceof SyntaxError?'无法读取 JSON，请检查备份文件':e.message);}finally{$('importFile').value='';}
};
