    ['狮子座','日冕绽放',[0,7,11,14],349,'triangle'],
    ['处女座','水晶阶梯',[0,4,9,12],440,'sine'],
    ['天秤座','平衡和弦',[0,7,4,12],330,'sine'],
    ['天蝎座','深空脉动',[0,3,7,12],196,'triangle'],
    ['射手座','流星飞越',[0,5,12,19],294,'triangle'],
    ['摩羯座','山岳回声',[0,7,2,9],247,'triangle'],
    ['水瓶座','星际信号',[0,14,7,21],370,'sine'],
    ['双鱼座','星海浮光',[12,9,7,0],262,'sine']
