  function prepare(){if(ctx)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('当前浏览器暂不支持音效');ctx=new Audio();master=ctx.createGain();master.gain.value=.58;analyser=ctx.createAnalyser();analyser.fftSize=512;master.connect(analyser);analyser.connect(ctx.destination);}
